4385:     /// This function will panic if the two slices have different lengths.
4386:     ///
4387:     /// # Example
4388:     ///
4389:     /// Swapping two elements across slices:
4390:     ///
4391:     /// ```
4392:     /// let mut slice1 = [0, 0];
